def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Rows containing the horizontal patterns.
    bar_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 5]
    if not bar_rows:
        return out
    last_bar = max(bar_rows)

    # Columns marked by vertical patterns below the horizontal patterns.
    marker_cols = {
        c for r in range(last_bar + 1, h)
        for c in range(w) if grid[r][c] != 0
    }

    for c in marker_cols:
        anchors = []
        for r in bar_rows:
            if 0 < c < w - 1 and grid[r][c] == 0:
                color = grid[r][c - 1]
                if color != 0 and grid[r][c + 1] == color:
                    anchors.append((r, color))

        if not anchors:
            continue
        anchors.sort()

        # Extend each horizontal pattern upward, and fill the bands between them.
        first_r, first_color = anchors[0]
        for r in range(first_r + 1):
            out[r][c] = first_color

        for (prev_r, _), (r, color) in zip(anchors, anchors[1:]):
            for rr in range(prev_r + 1, r + 1):
                out[rr][c] = color

        # Continue the vertical marker's own color through any gaps below the bars.
        below = [grid[r][c] for r in range(last_bar + 1, h) if grid[r][c] != 0]
        if below:
            color = below[0]
            for r in range(anchors[-1][0] + 1, h):
                out[r][c] = color

    return out
